fn update(scene: &mut GameScene<'_>, time: &FrameTime) {
    // A 4 s round trip: up 3 m in 2 s, down in 2 s.
    let seconds = time.fixed_tick as f32 / 60.0;
    let phase = seconds % 4.0;
    let y = if phase < 2.0 { 1.5 * phase } else { 1.5 * (4.0 - phase) };
    if let Some(mut lift) = scene.try_object("Lift") {
        lift.set_position([0.0, y, 0.0]);
    }
    let trips = ((seconds + 2.0) / 4.0).floor() as i32;
    scene.set_counter("trips", trips);
}
